const MU = 3.986004418e14;
const R_ORBIT = 6378137 + 415000;
const N = Math.sqrt(MU / R_ORBIT ** 3);

function clamp(x,a,b){return Math.max(a,Math.min(b,x));}
function add(a,b){return [a[0]+b[0],a[1]+b[1],a[2]+b[2]];}
function sub(a,b){return [a[0]-b[0],a[1]-b[1],a[2]-b[2]];}
function scale(a,s){return [a[0]*s,a[1]*s,a[2]*s];}
function dot(a,b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}
function cross(a,b){return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]];}
function hypot3(a){return Math.hypot(a[0],a[1],a[2]);}
function normalize(a){const L=hypot3(a); if(L<1e-12) return [0,0,0]; return scale(a,1/L);}
function quatMul(a,b){
  const aw=a[0],ax=a[1],ay=a[2],az=a[3], bw=b[0],bx=b[1],by=b[2],bz=b[3];
  return [aw*bw-ax*bx-ay*by-az*bz, aw*bx+ax*bw+ay*bz-az*by, aw*by-ax*bz+ay*bw+az*bx, aw*bz+ax*by-ay*bx+az*bw];
}
function quatConj(q){return [q[0],-q[1],-q[2],-q[3]];}
function quatNorm(q){const L=Math.hypot(q[0],q[1],q[2],q[3])||1; return [q[0]/L,q[1]/L,q[2]/L,q[3]/L];}
function quatFromEuler(yaw,pitch,roll){
  const cy=Math.cos(yaw/2), sy=Math.sin(yaw/2);
  const cp=Math.cos(pitch/2), sp=Math.sin(pitch/2);
  const cr=Math.cos(roll/2), sr=Math.sin(roll/2);
  return [cr*cp*cy+sr*sp*sy, sr*cp*cy-cr*sp*sy, cr*sp*cy+sr*cp*sy, cr*cp*sy-sr*sp*cy];
}
function quatToMat(q){
  const w=q[0],x=q[1],y=q[2],z=q[3];
  const xx=x*x,yy=y*y,zz=z*z,xy=x*y,xz=x*z,yz=y*z,wx=w*x,wy=w*y,wz=w*z;
  return [
    [1-2*(yy+zz), 2*(xy-wz), 2*(xz+wy)],
    [2*(xy+wz), 1-2*(xx+zz), 2*(yz-wx)],
    [2*(xz-wy), 2*(yz+wx), 1-2*(xx+yy)],
  ];
}
function matToQuat(m){
  const tr=m[0][0]+m[1][1]+m[2][2];
  let w,x,y,z;
  if(tr>0){
    const s=Math.sqrt(tr+1)*2;
    w=0.25*s; x=(m[2][1]-m[1][2])/s; y=(m[0][2]-m[2][0])/s; z=(m[1][0]-m[0][1])/s;
  } else if(m[0][0]>m[1][1] && m[0][0]>m[2][2]){
    const s=Math.sqrt(1+m[0][0]-m[1][1]-m[2][2])*2;
    w=(m[2][1]-m[1][2])/s; x=0.25*s; y=(m[0][1]+m[1][0])/s; z=(m[0][2]+m[2][0])/s;
  } else if(m[1][1]>m[2][2]){
    const s=Math.sqrt(1+m[1][1]-m[0][0]-m[2][2])*2;
    w=(m[0][2]-m[2][0])/s; x=(m[0][1]+m[1][0])/s; y=0.25*s; z=(m[1][2]+m[2][1])/s;
  } else {
    const s=Math.sqrt(1+m[2][2]-m[0][0]-m[1][1])*2;
    w=(m[1][0]-m[0][1])/s; x=(m[0][2]+m[2][0])/s; y=(m[1][2]+m[2][1])/s; z=0.25*s;
  }
  return quatNorm([w,x,y,z]);
}
function mulMV(m,v){return [m[0][0]*v[0]+m[0][1]*v[1]+m[0][2]*v[2], m[1][0]*v[0]+m[1][1]*v[1]+m[1][2]*v[2], m[2][0]*v[0]+m[2][1]*v[1]+m[2][2]*v[2]];}
function mulMT(m,v){return [m[0][0]*v[0]+m[1][0]*v[1]+m[2][0]*v[2], m[0][1]*v[0]+m[1][1]*v[1]+m[2][1]*v[2], m[0][2]*v[0]+m[1][2]*v[1]+m[2][2]*v[2]];}

const q = quatFromEuler(-Math.PI/2, 0, 0);
const R = quatToMat(q);
console.log('port axis', mulMV(R,[1,0,0]).map(v=>+v.toFixed(4)));
const q2 = matToQuat(R);
console.log('roundtrip q', q.map(v=>+v.toFixed(4)), q2.map(v=>+v.toFixed(4)));
const axis = mulMV(R,[1,0,0]);
const xb = scale(axis,-1);
let yb = mulMV(R,[0,1,0]);
yb = normalize(sub(yb, scale(xb, dot(xb,yb))));
const zb = cross(xb, yb);
const Rd = [ [xb[0], yb[0], zb[0]], [xb[1], yb[1], zb[1]], [xb[2], yb[2], zb[2]] ];
const qd = matToQuat(Rd);
console.log('chaser x', mulMV(quatToMat(qd),[1,0,0]).map(v=>+v.toFixed(4)), 'want', xb.map(v=>+v.toFixed(4)));

// CW equilibrium V-bar
function cw(x,y,z,vx,vy,vz,ax=0,ay=0,az=0){
  return [3*N*N*x + 2*N*vy + ax, -2*N*vx + ay, -N*N*z + az];
}
console.log('vbar eq', cw(0,-30,0,0,0,0));
console.log('rbar eq needs ax', -cw(10,0,0,0,0,0)[0]);

// RK4 stability coast
function deriv(s,a){
  const x=s[0],y=s[1],z=s[2],vx=s[3],vy=s[4],vz=s[5];
  return [vx,vy,vz, 3*N*N*x+2*N*vy+a[0], -2*N*vx+a[1], -N*N*z+a[2]];
}
function add6(a,b){return a.map((v,i)=>v+b[i]);}
function sc6(a,s){return a.map(v=>v*s);}
function rk4(s,a,dt){
  const f=z=>deriv(z,a);
  const k1=f(s);
  const k2=f(add6(s,sc6(k1,dt/2)));
  const k3=f(add6(s,sc6(k2,dt/2)));
  const k4=f(add6(s,sc6(k3,dt)));
  return add6(s, sc6(add6(add6(k1,sc6(k2,2)), add6(sc6(k3,2),k4)), dt/6));
}
let s=[0.6,-42,-0.4,0,0.01,0];
for(let i=0;i<20000;i++) s=rk4(s,[0,0,0],0.05);
console.log('coast 1000s', s.map(v=>+v.toFixed(3)), 'finite', s.every(Number.isFinite));

// PD tracking
const MASS=500, AMAX=0.088, KP=0.01, KD=0.2;
function pd(s, rDes, vDes){
  const a=[KP*(rDes[0]-s[0])+KD*(vDes[0]-s[3]), KP*(rDes[1]-s[1])+KD*(vDes[1]-s[4]), KP*(rDes[2]-s[2])+KD*(vDes[2]-s[5])];
  const cwA=[3*N*N*s[0]+2*N*s[4], -2*N*s[3], -N*N*s[2]];
  let cmd=sub(a,cwA);
  const L=hypot3(cmd);
  if(L>AMAX) cmd=scale(cmd, AMAX/L);
  return cmd;
}
s=[0.6,-42,-0.4,0,0,0];
const des=[0,-28,0];
for(let i=0;i<4000;i++){ // 200s
  const a=pd(s, des, [0,0,0]);
  s=rk4(s,a,0.05);
}
console.log('track 200s', s.map(v=>+v.toFixed(3)), 'err', Math.hypot(s[0]-des[0], s[1]-des[1], s[2]-des[2]).toFixed(3));
