  {id:'+Z1', pos:[ 0.46, 0.30,-0.58], dir:[0,0,1]},
  {id:'+Z2', pos:[-0.46,-0.30,-0.58], dir:[0,0,1]},
  {id:'-Z1', pos:[ 0.46,-0.30, 0.58], dir:[0,0,-1]},
  {id:'-Z2', pos:[-0.46, 0.30, 0.58], dir:[0,0,-1]},
];
