      const c=col(t);
      const score=dot(c, rem);
      const n2=dot(c,c);
      if(score<=0) continue;
      let frac=Math.min(score/n2, 1-duty[t.id]);
      const gain=frac*score - 0.5*frac*frac*n2;
      if(!best || gain>best.gain) best={t, frac, gain, c};
