dev-browser << 'EOF'
const page = await browser.getPage("janus");
const errors = [];
page.on("pageerror", (err) => errors.push("pageerror: " + err.message));
page.on("console", (msg) => { if (msg.type() === "error" || msg.type() === "warning") errors.push(msg.type() + ": " + msg.text()); });
await page.goto("http://127.0.0.1:8765/index.html", { waitUntil: "domcontentloaded", timeout: 60000 });
await page.waitForFunction(() => window.__JANUS__, { timeout: 30000 });
await page.waitForTimeout(600);

const controls = await page.evaluate(async () => {
  const J = window.__JANUS__;
  const out = {};
  J.setScenario("sensor-blackout");
  out.blackout = J.snapshot().mission.scenario;
  J.setScenario("stuck-thruster");
  const stuck = J.snapshot();
  out.stuck = { scenario: stuck.mission.scenario, failed: stuck.actuator.failedId, time: stuck.mission.time };
  J.setScenario("nominal");
  J.reset(7);
  const a = J.snapshot();
  document.getElementById("btn-pause").click();
  const pausedFlag = document.body.dataset.paused;
  await new Promise((r) => setTimeout(r, 350));
  const b = J.snapshot();
  document.getElementById("btn-step").click();
  const c = J.snapshot();
  document.getElementById("btn-abort").click();
  const d = J.snapshot();
  const cams = ["cinematic", "target", "dock", "cockpit", "free"];
  const camStates = [];
  for (const cam of cams) {
    document.querySelector(`#cameras button[data-cam="${cam}"]`).click();
    camStates.push(document.body.dataset.camera);
  }
  document.getElementById("btn-reset-view").click();
  const box = document.querySelector('#overlays input[data-overlay="keepout"]');
  const before = box.checked;
  box.click();
  const after = box.checked;
  document.querySelector('#overlays input[data-overlay="plumes"]').click();
  out.pause = { pausedFlag, t0: a.mission.time, t1: b.mission.time, same: JSON.stringify(a.truth.r) === JSON.stringify(b.truth.r), tStep: c.mission.time, phaseAbort: d.guidance.phase };
  out.cams = camStates;
  out.overlay = { before, after };
  out.viewReset = document.body.dataset.camera;
  return out;
});

const progress = await page.evaluate(() => {
  const J = window.__JANUS__;
  J.setScenario("nominal");
  J.reset(21);
  const marks = [];
  for (const t of [30, 60, 100, 160, 240]) {
    J.step(t - (marks.at(-1)?.time || 0));
    const s = J.snapshot();
    marks.push({
      time: +s.mission.time.toFixed(1),
      phase: s.guidance.phase,
      cg: +s.safety.cgRange.toFixed(2),
      port: +s.safety.contact.range.toFixed(2),
      align: +s.safety.contact.alignDeg.toFixed(2),
      sigma: +s.estimate.positionSigma.toFixed(3),
      prop: +s.truth.propellant.toFixed(3),
      level: s.safety.level,
    });
  }
  const blackout = (() => {
    J.setScenario("sensor-blackout");
    const seen = [];
    let time = 0;
    while (time < 180) {
      J.step(5);
      time += 5;
      const s = J.snapshot();
      if (s.sensor.dropout || s.guidance.phase === "hold-point" || s.guidance.phase === "abort" || time % 20 === 0) {
        seen.push({ time: +s.mission.time.toFixed(1), phase: s.guidance.phase, drop: s.sensor.dropout, meas: s.sensor.measurement, sigma: +s.estimate.positionSigma.toFixed(3), cg: +s.safety.cgRange.toFixed(1) });
      }
      if (seen.filter((x) => x.drop).length && seen.some((x) => x.time > 50 && !x.drop)) break;
    }
    return seen.slice(0, 12);
  })();
  const fault = (() => {
    J.setScenario("stuck-thruster");
    const notes = [];
    for (let i = 0; i < 24; i++) {
      J.step(5);
      const s = J.snapshot();
      const x1 = s.actuator.thrusters.find((t) => t.id === "+X1");
      if (x1.isolated || i % 4 === 0) notes.push({ time: +s.mission.time.toFixed(1), phase: s.guidance.phase, isolated: x1.isolated, ach: +x1.impulseAchieved.toFixed(2), cmd: +x1.impulseCommanded.toFixed(2), cg: +s.safety.cgRange.toFixed(1), level: s.safety.level });
      if (x1.isolated) break;
    }
    return notes;
  })();
  return { marks, blackout, fault };
});

const shot = await page.screenshot({ fullPage: false });
const shotPath = await saveScreenshot(shot, "janus-desktop.png");
console.log(JSON.stringify({ controls, progress, errors, shotPath }, null, 2));
EOF

