      recovery = { t: snap.mission.time, sigma: snap.estimate.positionSigma, phase: snap.guidance.phase, meas: snap.sensor.measurement };
      break;
    }
  }
  return {
    contact: s.safety.contact,
    phase: s.guidance.phase,
    truthR: s.truth.r,
    estR: s.estimate.r,
    waypoint: s.guidance.waypoint,
    reason: s.guidance.reason,
    inCorridor: s.safety.inCorridor,
    cams,
    dropped,
    recovery,
  };
});
console.log(JSON.stringify(info, null, 2));
