const page = await browser.getPage("janus");
const errors = [];
page.on("pageerror", (err) => errors.push(err.message));
page.on("console", (msg) => { if (msg.type() === "error") errors.push(msg.text()); });
await page.goto("http://127.0.0.1:8765/index.html", { waitUntil: "domcontentloaded", timeout: 60000 });
await page.waitForFunction(() => window.__JANUS__);
const out = await page.evaluate(() => {
  const J = window.__JANUS__;
  const self = J.runSelfTest();
  J.setScenario("nominal");
  J.reset(21);
  const marks = [];
  let t = 0;
  while (t < 520) {
    J.step(20);
    t += 20;
    const s = J.snapshot();
    marks.push({ t: +s.mission.time.toFixed(0), phase: s.guidance.phase, cg: +s.safety.cgRange.toFixed(2), port: +s.safety.contact.range.toFixed(2), lat: +s.safety.contact.lateral.toFixed(2), align: +s.safety.contact.alignDeg.toFixed(2), close: +s.safety.contact.closing.toFixed(3), level: s.safety.level });
    if (s.guidance.phase === "hard-dock" || s.guidance.phase === "abort") break;
  }
  const cams = [];
  for (const cam of ["target", "dock", "cockpit", "free", "cinematic"]) {
    document.querySelector(`#cameras button[data-cam="${cam}"]`).click();
    const pressed = [...document.querySelectorAll("#cameras button[data-cam]")].filter((b) => b.getAttribute("aria-pressed") === "true").map((b) => b.dataset.cam);
    cams.push({ cam, body: document.body.dataset.camera, pressed });
  }
  document.querySelector('#overlays input[data-overlay="covariance"]').click();
  const cov = document.querySelector('#overlays input[data-overlay="covariance"]').checked;
  document.getElementById("btn-pause").click();
  return {
    self: self.passed,
    failed: self.tests.filter((t) => !t.pass).map((t) => t.name + ": " + t.detail),
    marks,
    cams,
    cov,
  };
});
await page.waitForTimeout(400);
const shot = await page.screenshot();
const shotPath = await saveScreenshot(shot, "janus-approach.png");
console.log(JSON.stringify({ ...out, errors, shotPath }, null, 2));
